import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Auth.css';

export default function Signup() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [msg, setMsg] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg('');

    if (!email || !password || !confirmPassword) {
      setMsg('Merci de remplir tous les champs');
      return;
    }
    if (password !== confirmPassword) {
      setMsg('Les mots de passe ne correspondent pas');
      return;
    }

    try {
      const res = await fetch('http://localhost:8000/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (res.ok) {
        alert('Compte créé avec succès ! Vous pouvez maintenant vous connecter.');
        navigate('/login');
      } else {
        const error = await res.json();
        setMsg(error.detail || 'Échec de l’inscription');
      }
    } catch (err) {
      setMsg('Impossible de joindre le serveur');
    }
  };

  return (
    <div className="auth-wrapper">
      <div className="dark-overlay"></div>
      <div className="auth-card">
        <h2>Créer un compte</h2>
        <form className="auth-form" onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Confirmer le mot de passe"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
          />
          <button className="auth-button" type="submit">S’inscrire</button>
        </form>
        {msg && <p style={{ color: 'red', marginTop: '1rem' }}>{msg}</p>}
        <div className="auth-footer">
          Déjà un compte ? <Link to="/login">Se connecter</Link>
        </div>
      </div>
    </div>
  );
}
